/// The bar down a row's left edge, in `mode`'s colour.
pub(super) fn mode_bar(mode: Option<SendMode>, cx: &App) -> Div {
    let color = mode.map_or(cx.theme().muted_foreground, |mode| {
        chat_input::mode_color(mode, cx)
    });
    div()
        .absolute()
        .left_0()
        .top_0()
        .bottom_0()
        .w(MODE_BAR)
        .bg(color)
}

