p='prompt_mode/tasks_tab.rs'; s=open(p).read()
def rep(a,b):
    global s
    assert a in s, a
    s=s.replace(a,b,1)
rep('''/// How wide the bar down a row's left edge is, in its mode's colour.
const MODE_BAR: Pixels = px(2.);''','''/// How wide the bar down a body task tab's left edge is, in its mode's
/// colour.
const MODE_BAR: Pixels = px(2.);

/// The bar in a Tasks tab row's mode's colour, as the TasksTabScope's rows
/// say: a pill this wide, its corners rounded this much, set in from the
/// row's left and from its top and bottom by these.
const ROW_BAR: Pixels = px(4.);
const ROW_BAR_RADIUS: Pixels = px(2.);
const ROW_BAR_LEFT: Pixels = px(4.);
const ROW_BAR_INSET: Pixels = px(6.);''')
rep('''/// A group's heading: its label, muted, then what goes along it.''','''/// The bar in `mode`'s colour at a Tasks tab row's left: a short rounded
/// pill, inset from the row's edges, so the bars of rows one above another
/// never touch.
fn row_bar(mode: Option<SendMode>, cx: &App) -> Div {
    let color = mode.map_or(cx.theme().muted_foreground, |mode| {
        chat_input::mode_color(mode, cx)
    });
    div()
        .absolute()
        .left(ROW_BAR_LEFT)
        .top(ROW_BAR_INSET)
        .bottom(ROW_BAR_INSET)
        .w(ROW_BAR)
        .rounded(ROW_BAR_RADIUS)
        .bg(color)
}

/// A group's heading: its label, muted, then what goes along it.''')
rep('''            .child(mode_bar(task.mode, cx).when(step.is_some(), |bar| bar.left(STEP_INDENT)))''','''            .child(row_bar(task.mode, cx).when(step.is_some(), |bar| bar.left(STEP_INDENT + ROW_BAR_LEFT)))''')
rep('''            .child(mode_bar(Some(SendMode::Both), cx))''','''            .child(row_bar(Some(SendMode::Both), cx))''')
rep('''                    .child(mode_bar(item.mode, cx))''','''                    .child(row_bar(item.mode, cx))''')
rep('''                .child(mode_bar(Some(step.mode), cx))''','''                .child(row_bar(Some(step.mode), cx))''')
open(p,'w').write(s)
EOF
